    ox, oy = pos(g.get("opponent_position", g.get("opponent", g.get("enemy", (0, 0)))))

    blocked = set()
    for k in ("obstacles", "walls", "blocked", "hazards"):
        for v in arr(g.get(k, [])):
            blocked.add(pos(v.get("position", v)) if isinstance(v, dict) else pos(v))

    targets = []
    for k in ("resources", "resource_positions", "targets", "control_points", "points", "goals", "objectives"):
        for v in arr(g.get(k, [])):
